```javascript
const groupLogsByType = (
  rawLogs: T.BuildLog[],
  filterType: FilterState,
): FilteredLog[] => {
  if (filterType === 'all') {
    return [{ hidden: false, logs: rawLogs }];
  }

  const logs = rawLogs.map((l, index) => ({ ...l, index }));
  const groups: { hidden: boolean; logs: BuildLogWithIndex[] }[] = [];

  let currentGroup: BuildLogWithIndex[] = [];
  let currentGroupType: FilterState = 'all';
  for (const log of logs) {
    let logType: FilterState = 'all';
    if (log.error) {
      logType = 'errors';
    } else if (log.warning) {
      logType = 'warnings';
    }

    if (logType !== currentGroupType) {
      if (currentGroup.length > 0) {
        groups.push({ hidden: currentGroupType !== filterType, logs: currentGroup });
      }
      currentGroup = [log];
      currentGroupType = logType;
    } else {
      currentGroup.push(log);
    }
  }

  // Group together neighboring groups that are either both hidden or visible.
  if (currentGroup.length > 0) {
    groups.push({ hidden: currentGroupType !== filterType, logs: currentGroup });
  }

  // Compact neighboring groups
  const compactedGroups = groups.reduce((prev, cur) => {
    const isCurrentGroupHidden = cur.hidden;
    const previousGroup = prev[prev.length - 1];
    const isPreviousGroupHidden = previousGroup !== undefined ? previousGroup.hidden : isCurrentGroupHidden;

    if (isCurrentGroupHidden === isPreviousGroupHidden) {
      if (prev.length === 0) {
        return [cur];
      }
      previousGroup.logs.push(...cur.logs);
      return prev;
    }
    return prev.concat(cur);
  }, []);

  return compactedGroups;
};
```

