Here is an AWS Lambda function written in Go that deletes EBS Snapshots based on the specified retention policy:
```go
package main

import (
	"context"
	"fmt"
	"log"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
)

func handler(ctx context.Context) (interface{}, error) {
	// Create an EC2 client
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		log.Println(err)
		return nil, err
	}
	ec2Client := ec2.New(sess)

	// Define the retention policy as a map
	retentionPolicy := map[string]int{
		"monthly": 14,
		"daily":   10,
		"weekly":  4,
		"yearly":  1,
	}

	// Get all EBS Snapshots with the "backup_type" tag
	snapshots, err := ec2Client.DescribeSnapshots(&ec2.DescribeSnapshotsInput{
		Filter: []*ec2.Filter{
			{
				Name: aws.String("tag:backup_type"),
			},
		},
	})
	if err != nil {
		log.Println(err)
		return nil, err
	}

	// Delete snapshots that are beyond their retention period
	for _, snapshot := range snapshots.Snapshots {
		delSnap, err := ec2Client.DeleteSnapshot(&ec2.DeleteSnapshotInput{
			SnapshotId: snapshot.SnapshotId,
		})
		if err != nil {
			log.Println(err)
			return nil, err
		}
		switch snapshot.Tags[0].Value {
		case "monthly":
			if int(delSnap.Result *) - retentionPolicy["monthly"] {
				fmt.Println("Deleting monthly snapshot:", snapshot.SnapshotId)
			}
		case "daily":
			if int(delSnap.Result *) - retentionPolicy["daily"] {
				fmt.Println("Deleting daily snapshot:", snapshot.SnapshotId)
			}
		case "weekly":
			if int(delSnap.Result *) - retentionPolicy["weekly"] {
				fmt.Println("Deleting weekly snapshot:", snapshot.SnapshotId)
			}
		case "yearly":
			if int(delSnap.Result *) - retentionPolicy["yearly"] {
				fmt.Println("Deleting yearly snapshot:", snapshot.SnapshotId)
			}
		}
	}

